//! DD-RUL-013 and IFP-RUL-6: the ECO table and `eco::lookup`, generated by `build.rs` from
//! `third_party/eco/` (D-20, D-75). The table is an immutable `static` sorted by key, so it
//! needs no lazy initialisation and no lock. The "deepest named position" rule and everything
//! about a game stay in `chess-domain`.

use crate::position::PositionKey;

/// The code and English name of a named position.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct EcoEntry {
    pub code: &'static str,
    pub name: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/eco_generated.rs"));

/// The entry for the position, or `None` when no opening names it. Depends only on the key.
pub fn lookup(key: &PositionKey) -> Option<EcoEntry> {
    let epd = key.to_epd();
    TABLE
        .binary_search_by(|(k, _)| (*k).cmp(epd.as_str()))
        .ok()
        .and_then(|i| TABLE.get(i))
        .map(|(_, entry)| *entry)
}
